    @MainActor
    enum RegressionRepositoryAdapters {
        static func prepareNavigation(
            on process: InitializationProcess,
        ) async throws {
            try RegressionFixtures.prepareSpeechStorage()
            if UserDefaults.standard.bool(
                forKey: "regressionResetLegalConsent",
            ) {
                try await process.sharedRepository!.acceptLegal(
                    documentDate: .distantPast,
                )
            }
        }

        static func install(
            on process: InitializationProcess,
        ) {
            guard !(process.templateRepository is RegressionTemplateRepository) else {
                return
            }
            let faults = RegressionRepositoryFaults()
            process.sharedRepository = RegressionSharedRepository(
                wrapped: process.sharedRepository!,
                faults: faults,
            )
            process.userSettingsRepository = RegressionUserSettingsRepository(
                wrapped: process.userSettingsRepository!,
                faults: faults,
            )
            process.settingsAIRepository = RegressionSettingsAIRepository(
                wrapped: process.settingsAIRepository!,
                faults: faults,
            )
            process.ultrasoundReportRepository = RegressionUltrasoundReportRepository(
                wrapped: process.ultrasoundReportRepository!,
                faults: faults,
            )
            process.ultrasoundDraftRepository = RegressionUltrasoundDraftRepository(
                wrapped: process.ultrasoundDraftRepository!,
                faults: faults,
            )
            process.templateRepository = RegressionTemplateRepository(
                wrapped: process.templateRepository!,
                faults: faults,
            )
            let model = process.applicationConfig!.ultrasound.examinationNeuralModel
            process.examinationNeuralModelFactory = DNeuralUltrasoundModelFactory(
                locale: process.language!.currentLocale,
                proposalPrompt: model.proposalPrompt,
                parameters: DNeuralGenerationParameters(
                    temperature: model.temperature,
                    maxTokens: model.maxTokens,
                    maxContextTokens: model.maxContextTokens,
                ),
                parseDictation: process.ultrasoundReportRepository!.parseDictation,
            )
        }
    }

    @MainActor
    final class RegressionRepositoryFaults {
        @TaskLocal static var module: String?
        private let operation = UserDefaults.standard.string(
            forKey: "regressionFault",
        ) ?? ""
        private let targetModule = UserDefaults.standard.string(
            forKey: "regressionFaultModule",
        ) ?? ""
        private var skip = UserDefaults.standard.integer(
            forKey: "regressionFaultAfter",
        )
        private let delayedOperation = UserDefaults.standard.string(
            forKey: "regressionDelay",
        ) ?? ""
        private let delaySeconds = max(
            5,
            min(
                30,
                UserDefaults.standard.integer(
                    forKey: "regressionDelaySeconds",
                ),
            ),
        )
        private var delayConsumed = false
        private var consumed = false

        init() {}

        func check(
            _ name: String,
        ) async throws {
            if !delayConsumed, name == delayedOperation {
                delayConsumed = true
                try await Task.sleep(
                    for: .seconds(
                        delaySeconds,
                    ),
                )
            }
            guard !consumed, name == operation else {
                return
            }
            guard targetModule.isEmpty || Self.module == targetModule else {
                return
            }
            if skip > 0 {
                skip -= 1
                return
            }
            consumed = true
            throw CocoaError(
                .fileWriteUnknown,
            )
        }
    }

